<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('student');$sid=(int)current_user()['id'];$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title,a.id attempt_id,a.status attempt_status,a.score FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id JOIN class_students cs ON cs.class_id=e.class_id AND cs.student_id=? LEFT JOIN attempts a ON a.exam_id=e.id AND a.student_id=? WHERE e.status='published' AND (e.starts_at IS NULL OR e.starts_at<=NOW()) AND (e.ends_at IS NULL OR e.ends_at>=NOW()) ORDER BY e.id DESC");$s->execute([$sid,$sid]);$exams=$s->fetchAll();$r=db()->prepare('SELECT a.*,e.title exam_title,s.title subject_title FROM attempts a JOIN exams e ON e.id=a.exam_id JOIN subjects s ON s.id=e.subject_id WHERE a.student_id=? AND a.status IN ("submitted","reviewed") ORDER BY a.submitted_at DESC');$r->execute([$sid]);$results=$r->fetchAll();$average=$results?array_sum(array_map(fn($x)=>(float)($x['percentage']??0),$results))/count($results):0;$title='پنل دانش‌آموز';require __DIR__.'/../partials/header.php';?><div class="student-hero"><div><span class="eyebrow">باشگاه یادگیری</span><h1>سلام <?=e(current_user()['full_name'])?>!</h1><p>آماده‌ای مهارت‌های جدیدت را محک بزنی؟</p><div class="student-hero-actions"><a class="btn btn-light" href="#active-exams">مشاهده آزمون‌ها</a><a class="btn student-outline-btn" href="#results">کارنامه من</a><a class="btn student-outline-btn" href="<?=e(url('student/feedback.php'))?>">بازخوردهای من</a></div></div><div class="student-orbit"><span>یاد بگیر</span><b>پیشرفت کن</b></div></div><div class="student-stat-grid"><div class="student-stat-card sky"><span class="stat-emoji">آزمون</span><strong><?=number_format(count($exams))?></strong><small>آزمون فعال</small></div><div class="student-stat-card mint"><span class="stat-emoji">نتیجه</span><strong><?=number_format(count($results))?></strong><small>نتیجه ثبت‌شده</small></div><div class="student-stat-card pink"><span class="stat-emoji">رشد</span><strong><?=format_score($average)?>%</strong><small>میانگین عملکرد</small></div><div class="student-stat-card yellow"><span class="stat-emoji">هدف</span><strong><?=count(array_filter($exams,fn($e)=>!$e['attempt_id']))?></strong><small>در انتظار پاسخ</small></div></div><section id="active-exams" class="student-section"><div class="section-heading"><div><span class="eyebrow">وقت درخشیدن</span><h2>آزمون‌های فعال</h2></div><span class="student-section-badge">آماده‌ای؟</span></div><div class="student-exam-grid"><?php if(!$exams):?><div class="student-empty"><div class="empty-bubble">خوبی!</div><h3>فعلاً آزمون فعالی نداری</h3><p>به‌محض انتشار آزمون جدید، اینجا نمایش داده می‌شود.</p></div><?php else:foreach($exams as $i=>$exam):?><article class="student-exam-card card-tone-<?=($i%4)+1?>"><div class="student-card-shape"></div><div class="student-card-content"><div class="student-exam-head"><span class="student-subject"><?=e($exam['subject_title'])?></span><span class="student-duration"><?=e((string)$exam['duration_minutes'])?> دقیقه</span></div><h3><?=e($exam['title'])?></h3><p><?=e($exam['class_title'])?></p><div class="student-card-footer"><span><?= $exam['attempt_id'] ? 'پاسخ ثبت شده' : 'هنوز شروع نشده' ?></span><?php if(!$exam['attempt_id']):?><a class="btn btn-sm student-start-btn" href="<?=e(url('student/exam.php?id='.$exam['id']))?>">شروع آزمون</a><?php else:?><a class="btn btn-sm student-result-btn" href="<?=e(url('student/result.php?id='.$exam['attempt_id']))?>">مشاهده نتیجه</a><?php endif;?></div></div></article><?php endforeach;endif;?></div></section><section id="results" class="student-section"><div class="section-heading"><div><span class="eyebrow">مسیر پیشرفت</span><h2>آخرین کارنامه‌ها</h2></div><span class="student-section-badge">ادامه بده!</span></div><div class="student-results-grid"><?php if(!$results):?><div class="student-empty"><h3>هنوز کارنامه‌ای ثبت نشده</h3><p>اولین آزمونت را انجام بده تا نتیجه‌ات اینجا دیده شود.</p></div><?php else:foreach($results as $result):?><a class="student-result-card" href="<?=e(url('student/result.php?id='.$result['id']))?>"><span class="result-dot"></span><div><strong><?=e($result['exam_title'])?></strong><small><?=e($result['subject_title'])?></small></div><b><?=format_score($result['percentage'])?>%</b><span class="result-arrow">←</span></a><?php endforeach;endif;?></div></section><?php require __DIR__.'/../partials/footer.php'; ?>
